def is_balanced(s: str) -> bool:
    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return len(stack) == 0
